
apa() { 
pwd="${PWD}"; printf %b "\n.... to update run [apass] ....\n"; 
cd $HOME/logs/apts &>/dev/null; aapp=($(ls|fzf -i -m --color preview-bg:18 --bind "q:abort" --preview "tac {}|tail -c+2|bat -ppflzig" --preview-window "wrap,16,top,noborder" --border none --cycle --ansi --inline-info))||(printf %b " OK  \n\n"&& cd $pwd &>/dev/null&& return 1;)||return 1; cd $pwd &>/dev/null&& printf %b " OK \n"; (printf %b " -- Install: "; printf %b "${aapp[*]}"|tr -s " " ","; printf %b "\b ? [Y/n] ")|bat -pflc --theme Nord; cd $pwd &>/dev/null; read -r -s -n1 ny; [ $ny ]&& printf %b "\e[92m OK\e[0m \n\n" && cd $pwd &>/dev/null && return 0; hash sudo 2>/dev/null && sudo=sudo; $sudo apt update 2>/dev/null|bat -ppflzig --theme Nord; $sudo apt install -y ${aapp[*]} 2>/dev/null|bat -ppflzig --theme Nord; cd $pwd; printf %b " OK  \n\n"; }; 
